  g_img_data = rgb565;
  g_img_w = w;
  g_img_h = h;
  g_img_pending = true;
}

void ui_app_hide_image(void)
{
  g_img_pending = false;

  /* 删除对象而非仅隐藏：隐藏只加 flag，对象仍留在屏幕上并干扰后续
   * 渲染（曾见 img test 色块残留在首页主内容区）。 */

  if (g_img_test != NULL)
    {
      lv_obj_delete(g_img_test);
      g_img_test = NULL;
    }
}

