{
  int row;

  /* Prepare row buffer for landscape mode (480 pixels wide) */

  uint8_t landscape_row_buf[ST7789_YRES * 2];

  for (int i = 0; i < ST7789_YRES; i++)
    {
      landscape_row_buf[i * 2]     = (uint8_t)(color >> 8);
      landscape_row_buf[i * 2 + 1] = (uint8_t)(color & 0xff);
