  fputc('B', fp);
  fputc('M', fp);
  ui_cap_put32(fp, 66u + (uint32_t)480 * 320 * 2u);
  ui_cap_put16(fp, 0);
  ui_cap_put16(fp, 0);
  ui_cap_put32(fp, 66u);

  ui_cap_put32(fp, 40u);
  ui_cap_put32(fp, 480u);
  ui_cap_put32(fp, (uint32_t)(0u - 320u));  /* 负高，top-down */
  ui_cap_put16(fp, 1);
  ui_cap_put16(fp, 16);
  ui_cap_put32(fp, 3u);                      /* BI_BITFIELDS */
  ui_cap_put32(fp, (uint32_t)480 * 320 * 2u);
  ui_cap_put32(fp, 2835u);
  ui_cap_put32(fp, 2835u);
  ui_cap_put32(fp, 0u);
  ui_cap_put32(fp, 0u);

