/****************************************************************************
 * apps/plant-companion/ui/screens/screen_home.c
 *
 * ① 主界面 — 植物状态总览
 *   - 状态栏（时间/植物/电池/天气）
 *   - 欢迎语：早安，小绿！/今天是养花第 N 天
 *   - 植物卡片：名字/品种/心情 + 右侧健康分进度环
 *   - 数据行：水分/温度/光照/EC 四张小卡
 *   - 底部 4-Tab 导航
 *
 * 3A 阶段：布局完整、数据为占位（screen_home_refresh 预留接口，
 * 3B 阶段由 sensor_service/plant_state 驱动刷新）。
 ****************************************************************************/

#include <lvgl/lvgl.h>
#include <stdio.h>

#include "screen_home.h"
#include "screen_camera.h"
#include "screen_voice.h"
#include "../ui_app.h"
#include "../theme/theme_plant.h"
#include "../widgets/widget_topbar.h"
#include "../widgets/widget_bottomnav.h"

#ifdef CONFIG_ESP32S3_WIFI
#  include "screen_ota.h"
#endif

/****************************************************************************
 * Private Data（对象句柄，供 refresh 用）
 ****************************************************************************/

static lv_obj_t *s_arc;              /* 健康分进度环 */
static lv_obj_t *s_arc_value;        /* 进度环中心数字 */
static lv_obj_t *s_moisture;         /* 水分值 label */
static lv_obj_t *s_temp;             /* 温度值 label */
static lv_obj_t *s_light;            /* 光照值 label */
static lv_obj_t *s_ec;               /* EC 值 label */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* 数据小卡：图标 + 数值 + 单位 + 评语 */

static lv_obj_t *home_metric_card(lv_obj_t *parent, const char *icon,
                                  const char *unit, const char *note)
{
  lv_obj_t *card = lv_obj_create(parent);
  lv_obj_remove_style_all(card);
  lv_obj_add_style(card, &theme_style_card_small, 0);
  lv_obj_set_size(card, 108, 84);
  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_CENTER);
  lv_obj_set_style_pad_all(card, 8, 0);

  /* 图标行 */

  lv_obj_t *icon_label = lv_label_create(card);
  lv_label_set_text(icon_label, icon);
  /* 2026-09-03：图标行改用 TP_FONT_TITLE（zh 主字体）→ 走 zh_font.c
   * 兜底链（zh→montserrat→emoji）：LV_SYMBOL_* 由 montserrat 渲染，
   * 真 emoji（如 🌡）由 lv_font_emoji 渲染——此前 montserrat_20 无
   * fallback，emoji 图标全画占位方块。 */
  lv_obj_set_style_text_font(icon_label, TP_FONT_TITLE, 0);
  lv_obj_set_style_text_color(icon_label, lv_color_hex(TP_CLR_PRIMARY_GREEN_DARK), 0);

  /* 数值 + 单位（大数字） */

  lv_obj_t *value = lv_label_create(card);
  lv_label_set_text(value, unit);
  lv_obj_set_style_text_font(value, TP_FONT_TITLE, 0);

  /* 评语（次要文字） */

  lv_obj_t *note_label = lv_label_create(card);
  lv_label_set_text(note_label, note);
  lv_obj_add_style(note_label, &theme_style_text_sub, 0);

  return card;
}

static lv_obj_t *home_metric_value(lv_obj_t *card)
{
  return (lv_obj_t *)lv_obj_get_child(card, 1);
}

