  /* 标题 */

  title = lv_label_create(content);
  lv_label_set_text(title, "小绿绿的日记 · 8月");
  lv_obj_set_style_text_font(title, TP_FONT_TITLE, 0);
  lv_obj_set_style_text_color(title, lv_color_hex(TP_CLR_PRIMARY_GREEN_DARK), 0);

  /* 成就徽章行（3D-2）：已解锁 🏅 / 未解锁 ⭕ */

